if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['error'=>'Method not allowed'],405);$b=json_decode(file_get_contents('php://input'),true)??[];$id=(int)($b['product_id']??0);$email=trim((string)($b['email']??''));$first=trim((string)($b['firstName']??''));$last=trim((string)($b['lastName']??''));$phone=trim((string)($b['phone']??''));$customer=$b['customer']??[];if($id<1||!filter_var($email,FILTER_VALIDATE_EMAIL)||$first===''||$last==='')json_response(['error'=>'Informations client invalides'],422);
